 * 并发与幂等边界（真实多线程，不用睡眠代替断言）：
 * 并发分配不重席位；同 requestId 并发恰好一次业务执行且全部得到成功回放；
 * 同键异参并发只有一次成功，其余 409。
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ConcurrencyTest extends AbstractBlindIntegrationTest {

    @Autowired
    private TestRestTemplate rest;

    private HttpHeaders headers(String actor, String role, String requestId) {
        HttpHeaders h = new HttpHeaders();
        h.set("X-Actor-Id", actor);
        h.set("X-Role", role);
        if (requestId != null) {
            h.set("X-Request-Id", requestId);
        }
        h.setContentType(MediaType.APPLICATION_JSON);
        return h;
    }

    private <T> T runConcurrent(List<Callable<T>> tasks, int expected) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(Math.min(expected, 8));
        try {
            List<Future<T>> futures = new ArrayList<>();
            for (Callable<T> task : tasks) {
                futures.add(pool.submit(task));
            }
            for (Future<T> future : futures) {
                future.get(30, TimeUnit.SECONDS);
