package com.example.starter.blind;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * 幂等与鉴权边界：
 * 同键同参重放原结果；异参/异操作者 409；失败不占键可换键成功；
 * 权限校验先于幂等回放；缺头 401。
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class IdempotencyAndAuthTest extends AbstractBlindIntegrationTest {

    @Autowired
    private TestRestTemplate rest;

    private final ObjectMapper mapper = new ObjectMapper();

    private HttpHeaders headers(String actor, String role, String requestId) {
        HttpHeaders h = new HttpHeaders();
        if (actor != null) {
            h.set("X-Actor-Id", actor);
        }
        if (role != null) {
            h.set("X-Role", role);
        }
        if (requestId != null) {
            h.set("X-Request-Id", requestId);
        }
        h.setContentType(MediaType.APPLICATION_JSON);
        return h;
    }

    private ResponseEntity<String> post(String path, HttpHeaders headers, String body) {
        return rest.exchange(path, HttpMethod.POST, new HttpEntity<>(body, headers), String.class);
    }

    private JsonNode json(ResponseEntity<String> response) throws Exception {
        assertNotNull(response.getBody());
        return mapper.readTree(response.getBody());
    }

    @Test
    void replaySameKeySameParams_returnsOriginalResult_andNoDuplicateBusinessRow() throws Exception {
        ResponseEntity<String> first = post("/api/experiments/IDEM-1",
                headers("c1", "COORDINATOR", "idem-key-1"), "{\"blockCount\":3}");
        assertEquals(201, first.getStatusCode().value());
        JsonNode firstBody = json(first);
        assertEquals(3, firstBody.path("blockCount").asInt());

        // 同键同参同操作者重放：原结果（201 与相同响应体），不产生第二个实验
        ResponseEntity<String> replay = post("/api/experiments/IDEM-1",
                headers("c1", "COORDINATOR", "idem-key-1"), "{\"blockCount\":3}");
        assertEquals(201, replay.getStatusCode().value());
        assertEquals(first.getBody(), replay.getBody());

        // 不带 requestId 的同业务请求会命中“实验已存在”409，证明重放不是重新执行业务
        ResponseEntity<String> noIdem = post("/api/experiments/IDEM-1",
                headers("c1", "COORDINATOR", "idem-key-other"), "{\"blockCount\":3}");
        assertEquals(409, noIdem.getStatusCode().value());

        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM experiment WHERE id = 'IDEM-1'", Integer.class));
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-1'",
                Integer.class));
    }

    @Test
    void sameKeyDifferentParamsOrActor_conflicts() {
        assertEquals(201, post("/api/experiments/IDEM-2",
                headers("c1", "COORDINATOR", "idem-key-2"), "{\"blockCount\":2}")
                .getStatusCode().value());

        // 异参（不同 blockCount）：409
        assertEquals(409, post("/api/experiments/IDEM-2",
                headers("c1", "COORDINATOR", "idem-key-2"), "{\"blockCount\":4}")
                .getStatusCode().value());

        // 异操作者：409
        assertEquals(409, post("/api/experiments/IDEM-2",
                headers("c2", "COORDINATOR", "idem-key-2"), "{\"blockCount\":2}")
                .getStatusCode().value());

        // 异角色（同一 actorId 换 REVIEWER）：权限校验先于幂等回放，直接 403
        assertEquals(403, post("/api/experiments/IDEM-2",
                headers("c1", "REVIEWER", "idem-key-2"), "{\"blockCount\":2}")
                .getStatusCode().value());
    }

    @Test
    void failedRequest_doesNotConsumeKey() {
        // 非法 blockCount：400，失败不占键
        ResponseEntity<String> failed = post("/api/experiments/IDEM-3",
                headers("c1", "COORDINATOR", "idem-key-3"), "{\"blockCount\":1}");
        assertEquals(400, failed.getStatusCode().value());
        assertEquals(0, jdbc.queryForObject(
                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-3'",
                Integer.class));

        // 同一 requestId 换成合法参数：成功，证明失败未占键
        ResponseEntity<String> success = post("/api/experiments/IDEM-3",
                headers("c1", "COORDINATOR", "idem-key-3"), "{\"blockCount\":2}");
        assertEquals(201, success.getStatusCode().value());

        // 业务冲突失败（重复创建）也不占新键：先制造已存在实验，再用新键冲突，
        // 再用该键创建另一个实验应成功。
        ResponseEntity<String> conflict = post("/api/experiments/IDEM-3",
                headers("c1", "COORDINATOR", "idem-key-4"), "{\"blockCount\":2}");
        assertEquals(409, conflict.getStatusCode().value());
        assertEquals(0, jdbc.queryForObject(
                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-4'",
                Integer.class));
        assertEquals(201, post("/api/experiments/IDEM-4",
                headers("c1", "COORDINATOR", "idem-key-4"), "{\"blockCount\":2}")
                .getStatusCode().value());
    }

    @Test
    void missingRequestId_isBadRequest() {
        ResponseEntity<String> resp = post("/api/experiments/IDEM-5",
                headers("c1", "COORDINATOR", null), "{\"blockCount\":2}");
        assertEquals(400, resp.getStatusCode().value());
    }

    @Test
    void authHeaders_missingOrBadRole_unauthorized_andPrecedesIdempotency() {
        // 无任何身份头：401，不触达幂等表
        ResponseEntity<String> noHeaders = post("/api/experiments/IDEM-6",
                headers(null, null, "idem-key-6"), "{\"blockCount\":2}");
        assertEquals(401, noHeaders.getStatusCode().value());

        // 非法角色：401
        ResponseEntity<String> badRole = post("/api/experiments/IDEM-6",
                headers("c1", "ADMIN", "idem-key-6"), "{\"blockCount\":2}");
        assertEquals(401, badRole.getStatusCode().value());

        // 先用合法协调员成功占用 requestId
        assertEquals(201, post("/api/experiments/IDEM-6",
                headers("c1", "COORDINATOR", "idem-key-6"), "{\"blockCount\":2}")
                .getStatusCode().value());

        // 权限不足（REVIEWER 做协调员操作）必须 403，而非按幂等回放/409——权限先于幂等
        ResponseEntity<String> reviewerReplay = post("/api/experiments/IDEM-6",
                headers("c1", "REVIEWER", "idem-key-6"), "{\"blockCount\":2}");
        assertEquals(403, reviewerReplay.getStatusCode().value());

        // 缺身份头同样 401，而不是回放
        assertEquals(401, post("/api/experiments/IDEM-6",
                headers(null, null, "idem-key-6"), "{\"blockCount\":2}")
                .getStatusCode().value());
    }

    @Test
    void reviewerCannotCreateOrAllocate_coordinatorCannotApprove() {
        assertEquals(201, post("/api/experiments/IDEM-7",
                headers("c1", "COORDINATOR", "idem-key-7"), "{\"blockCount\":2}")
                .getStatusCode().value());

        assertEquals(403, post("/api/experiments/IDEM-8",
                headers("r1", "REVIEWER", "idem-key-8"), "{\"blockCount\":2}")
                .getStatusCode().value());
        assertEquals(403, post(
                "/api/experiments/IDEM-7/participants/P1/allocations",
                headers("r1", "REVIEWER", "idem-key-9"), null)
                .getStatusCode().value());
    }
}

package com.example.starter.blind.repo;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * 分配数据访问；seat_no 与 treatment 仅在库内与揭盲流程使用，不进入普通响应与日志。
 */
@Repository
public class AllocationRepository {

    /** 分配行（含盲底，仅供服务层内部使用）。 */
    public record AllocationRow(
            long id,
            String experimentId,
            String participantId,
            int blockNo,
            int seatNo,
            String blindCode,
            String status,
            String assignedActor,
            long assignedAt,
            Long withdrawnAt) {
    }

    private static final RowMapper<AllocationRow> ALLOCATION_MAPPER = (rs, n) -> new AllocationRow(
            rs.getLong("id"),
            rs.getString("experiment_id"),
            rs.getString("participant_id"),
            rs.getInt("block_no"),
            rs.getInt("seat_no"),
            rs.getString("blind_code"),
            rs.getString("status"),
            rs.getString("assigned_actor"),
            rs.getLong("assigned_at"),
            (Long) rs.getObject("withdrawn_at"));

    private final JdbcTemplate jdbc;

    public AllocationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(AllocationRow row) {
        jdbc.update("INSERT INTO allocation ("
                        + "experiment_id, participant_id, block_no, seat_no, blind_code, "
                        + "status, assigned_actor, assigned_at, withdrawn_at"
                        + ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                row.experimentId(), row.participantId(), row.blockNo(), row.seatNo(), row.blindCode(),
                row.status(), row.assignedActor(), row.assignedAt(), row.withdrawnAt());
    }

    public AllocationRow findByExperimentAndParticipant(String experimentId, String participantId) {
        List<AllocationRow> rows = jdbc.query(
                "SELECT id, experiment_id, participant_id, block_no, seat_no, blind_code, status, "
                        + "assigned_actor, assigned_at, withdrawn_at "
                        + "FROM allocation WHERE experiment_id = ? AND participant_id = ?",
                ALLOCATION_MAPPER, experimentId, participantId);
        return rows.isEmpty() ? null : rows.get(0);
    }

    /**
     * 原子领取按区组、席位顺序排列的第一个空位：把尚未被占用的最小 block_no/seat_no
     * 关联给新参与者。依赖 allocation(experiment_id, block_no, seat_no) 唯一索引兜底并发。
     *
     * @return 领取到的席位；实验满额时返回 null
     */
    public VacantSeat takeFirstVacantSeat(String experimentId, int blockCount) {
        List<VacantSeat> seats = jdbc.query(
                "SELECT s.block_no, s.seat_no FROM seat s "
                        + "LEFT JOIN allocation a "
                        + "ON a.experiment_id = s.experiment_id "
                        + "AND a.block_no = s.block_no "
                        + "AND a.seat_no = s.seat_no "
                        + "WHERE s.experiment_id = ? AND a.id IS NULL "
                        + "ORDER BY s.block_no, s.seat_no LIMIT 1",
                (rs, n) -> new VacantSeat(rs.getInt(1), rs.getInt(2)),
                experimentId);
        return seats.isEmpty() ? null : seats.get(0);
    }

    /** 原子领取结果。 */
    public record VacantSeat(int blockNo, int seatNo) {
    }

    public long countOccupied(String experimentId) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM allocation WHERE experiment_id = ?", Long.class, experimentId);
        return count == null ? 0 : count;
    }

    /**
     * 退组：仅 ASSIGNED -> WITHDRAWN，不释放席位。
     *
     * @return 受影响行数；0 表示不存在或已退组
     */
    public int markWithdrawn(long allocationId, long withdrawnAt) {
        return jdbc.update(
                "UPDATE allocation SET status = 'WITHDRAWN', withdrawn_at = ? "
                        + "WHERE id = ? AND status = 'ASSIGNED'",
                withdrawnAt, allocationId);
    }

    /**
     * 插入时若参与者已在同实验占席，抛出由唯一约束触发的 DuplicateKeyException。
     */
    public boolean isDuplicateParticipant(DuplicateKeyException e) {
        return e.getMessage() != null && e.getMessage().contains("uq_allocation_participant");
    }

    public boolean isDuplicateSeat(DuplicateKeyException e) {
        return e.getMessage() != null && e.getMessage().contains("uq_allocation_seat");
    }

    public boolean isDuplicateBlindCode(DuplicateKeyException e) {
        return e.getMessage() != null && e.getMessage().contains("uq_allocation_blind_code");
    }
}

package com.example.starter.blind.service;

import com.example.starter.blind.ApiException;
import com.example.starter.blind.Clock;
import com.example.starter.blind.dto.AllocationView;
import com.example.starter.blind.dto.ExperimentView;
import com.example.starter.blind.repo.AllocationRepository;
import com.example.starter.blind.repo.AllocationRepository.AllocationRow;
import com.example.starter.blind.repo.AllocationRepository.VacantSeat;
import com.example.starter.blind.repo.ExperimentRepository;
import com.example.starter.blind.repo.ExperimentRepository.ExperimentRow;
import com.example.starter.blind.repo.ExperimentRepository.SeatRow;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;

/**
 * 实验与分配核心业务：
 * 创建实验时固定区组与每区组两 A 两 B 的席位内容；分配按区组、席位顺序领取第一个空位；
 * 退组保留席位不重排；关闭后拒绝新增分配。普通视图不含席位号与处理代码。
 */
@Service
public class ExperimentService {

    static final int SEATS_PER_BLOCK = 4;

    private final ExperimentRepository experimentRepository;
    private final AllocationRepository allocationRepository;
    private final BlindCodeGenerator blindCodeGenerator;
    private final Clock clock;

    public ExperimentService(ExperimentRepository experimentRepository,
                             AllocationRepository allocationRepository,
                             BlindCodeGenerator blindCodeGenerator,
                             Clock clock) {
        this.experimentRepository = experimentRepository;
        this.allocationRepository = allocationRepository;
        this.blindCodeGenerator = blindCodeGenerator;
        this.clock = clock;
    }

    /**
     * 创建实验并固定席位：每区组按席位顺序两个 A、两个 B。
     * 不记录任何处理映射到日志。
     */
    @Transactional
    public ExperimentView createExperiment(String experimentId, int blockCount) {
        if (experimentId == null || experimentId.isBlank()) {
            throw ApiException.badRequest("experimentId 不能为空");
        }
        if (experimentRepository.findById(experimentId) != null) {
            throw ApiException.conflict("实验已存在: " + experimentId);
        }
        long now = clock.nowMillis();
        experimentRepository.insertExperiment(
                new ExperimentRow(experimentId, blockCount, "OPEN", now));
        List<SeatRow> seats = new ArrayList<>(blockCount * SEATS_PER_BLOCK);
        for (int blockNo = 1; blockNo <= blockCount; blockNo++) {
            for (int seatNo = 1; seatNo <= SEATS_PER_BLOCK; seatNo++) {
                // 按提交顺序：每区组前两席 A，后两席 B；内容创建后不可改。
                String treatment = seatNo <= 2 ? "A" : "B";
                seats.add(new SeatRow(experimentId, blockNo, seatNo, treatment));
            }
        }
        seats.forEach(experimentRepository::insertSeat);
        return new ExperimentView(experimentId, blockCount, SEATS_PER_BLOCK,
                blockCount * SEATS_PER_BLOCK, "OPEN", now);
    }

    public ExperimentView getExperiment(String experimentId) {
        ExperimentRow row = mustFindExperiment(experimentId);
        return new ExperimentView(row.id(), row.blockCount(), SEATS_PER_BLOCK,
                row.blockCount() * SEATS_PER_BLOCK, row.status(), row.createdAt());
    }

    /**
     * 原子领取第一个空位；实验行级锁串行化同实验并发分配。
     */
    @Transactional
    public AllocationView register(String experimentId, String participantId, String actorId) {
        if (participantId == null || participantId.isBlank()) {
            throw ApiException.badRequest("participantId 不能为空");
        }
        ExperimentRow experiment = experimentRepository.lockById(experimentId);
        if (experiment == null) {
            throw ApiException.notFound("实验不存在: " + experimentId);
        }
        if ("CLOSED".equals(experiment.status())) {
            throw ApiException.conflict("实验已关闭，拒绝新增分配");
        }
        AllocationRow existing =
                allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
        if (existing != null) {
            // 同实验同参与者只占一席；已退组也不重新占席。
            throw ApiException.conflict("参与者已在该实验登记，仅可占一席");
        }
        VacantSeat vacant = allocationRepository.takeFirstVacantSeat(experimentId,
                experiment.blockCount());
        if (vacant == null) {
            throw ApiException.full("实验席位已满");
        }
        long now = clock.nowMillis();
        AllocationRow inserted = insertWithUniqueBlindCode(experimentId, participantId, actorId,
                vacant, now);
        return toView(inserted);
    }

    private AllocationRow insertWithUniqueBlindCode(String experimentId, String participantId,
                                                    String actorId, VacantSeat vacant, long now) {
        // 盲码随机冲突概率极低，仍由唯一索引兜底并重试。
        for (int attempt = 0; attempt < 5; attempt++) {
            String blindCode = blindCodeGenerator.nextCode();
            AllocationRow row = new AllocationRow(0L, experimentId, participantId,
                    vacant.blockNo(), vacant.seatNo(), blindCode, "ASSIGNED",
                    actorId, now, null);
            try {
                allocationRepository.insert(row);
                return allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
            } catch (DuplicateKeyException e) {
                if (allocationRepository.isDuplicateBlindCode(e)) {
                    continue;
                }
                if (allocationRepository.isDuplicateSeat(e)
                        || allocationRepository.isDuplicateParticipant(e)) {
                    // 极端并发下由唯一约束兜底，按冲突处理，事务随幂等占位一并回滚。
                    throw ApiException.conflict("席位或参与者已被占用，请重试");
                }
                throw e;
            }
        }
        throw ApiException.conflict("盲码生成冲突，请重试");
    }

    /**
     * 退组：状态置为 WITHDRAWN 并记录时间；席位不释放、已有分配不重排。
     */
    @Transactional
    public AllocationView withdraw(String experimentId, String participantId) {
        AllocationRow allocation = mustFindAllocation(experimentId, participantId);
        if ("WITHDRAWN".equals(allocation.status())) {
            throw ApiException.conflict("参与者已退组");
        }
        allocationRepository.markWithdrawn(allocation.id(), clock.nowMillis());
        AllocationRow refreshed =
                allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
        return toView(refreshed);
    }

    /**
     * 关闭实验；已关闭再次关闭返回 409。
     */
    @Transactional
    public ExperimentView close(String experimentId) {
        ExperimentRow experiment = experimentRepository.lockById(experimentId);
        if (experiment == null) {
            throw ApiException.notFound("实验不存在: " + experimentId);
        }
        if ("CLOSED".equals(experiment.status())) {
            throw ApiException.conflict("实验已关闭");
        }
        experimentRepository.markClosed(experimentId);
        return new ExperimentView(experiment.id(), experiment.blockCount(), SEATS_PER_BLOCK,
                experiment.blockCount() * SEATS_PER_BLOCK, "CLOSED", experiment.createdAt());
    }

    /**
     * 普通查询：只返回盲码、区组号、参与者编号与退组状态。
     */
    public AllocationView getAllocation(String experimentId, String participantId) {
        return toView(mustFindAllocation(experimentId, participantId));
    }

    /** 内部使用的完整分配行（含盲底字段），禁止直接透出到普通响应。 */
    public AllocationRow mustFindAllocationRow(String experimentId, String participantId) {
        return mustFindAllocation(experimentId, participantId);
    }

    private AllocationRow mustFindAllocation(String experimentId, String participantId) {
        mustFindExperiment(experimentId);
        AllocationRow row =
                allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
        if (row == null) {
            throw ApiException.notFound("参与者尚未在该实验登记");
        }
        return row;
    }

    private ExperimentRow mustFindExperiment(String experimentId) {
        ExperimentRow row = experimentRepository.findById(experimentId);
        if (row == null) {
            throw ApiException.notFound("实验不存在: " + experimentId);
        }
        return row;
    }

    private AllocationView toView(AllocationRow row) {
        return new AllocationView(row.experimentId(), row.participantId(), row.blindCode(),
                row.blockNo(), row.status(), row.assignedAt(), row.withdrawnAt());
    }
}

